"""MathRichText safety + text extraction (docs/03 §4).

Rich text is structured blocks, never raw HTML. The browser renders text spans with textContent
and formulas with KaTeX (trust=false). Here we additionally reject LaTeX commands that can
fetch resources, define macros or inject markup, and check structural balance as a render pre-check.
"""
from __future__ import annotations

import re
from typing import Any, Iterator

# Commands that can load resources, define macros, emit HTML/links or run IO in some engines.
FORBIDDEN_LATEX = {
    "href", "url", "include", "input", "def", "gdef", "edef", "xdef", "newcommand", "renewcommand",
    "providecommand", "let", "futurelet", "write", "immediate", "openout", "openin", "read", "csname",
    "htmlClass", "htmlId", "htmlStyle", "htmlData", "includegraphics", "special", "catcode", "loop",
    "expandafter", "usepackage", "documentclass", "begingroup", "endgroup", "global",
}
_CMD_RE = re.compile(r"\\([A-Za-z]+)")


def latex_issues(latex: str) -> list[str]:
    """Return a list of blocking problems with a LaTeX fragment (empty = OK)."""
    issues: list[str] = []
    for cmd in _CMD_RE.findall(latex):
        if cmd in FORBIDDEN_LATEX:
            issues.append(f"forbidden command \\{cmd}")
    depth = 0
    escaped = False
    for ch in latex:
        if escaped:
            escaped = False
            continue
        if ch == "\\":
            escaped = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth < 0:
                issues.append("unbalanced braces")
                break
    if depth > 0:
        issues.append("unbalanced braces")
    if len(re.findall(r"\\left\b", latex)) != len(re.findall(r"\\right\b", latex)):
        issues.append("unbalanced \\left/\\right")
    if latex.count("\\begin{") != latex.count("\\end{"):
        issues.append("unbalanced \\begin/\\end")
    return issues


def iter_spans(rt: dict | None) -> Iterator[dict]:
    for block in (rt or {}).get("blocks", []):
        t = block.get("type")
        if t == "paragraph":
            yield from block.get("spans", [])
        elif t == "table":
            for row in block.get("rows", []):
                for cell in row:
                    yield from cell
        elif t == "list":
            for item in block.get("items", []):
                yield from item


def iter_latex(rt: dict | None) -> Iterator[str]:
    for span in iter_spans(rt):
        if span.get("type") == "inline_math":
            yield span["latex"]
    for block in (rt or {}).get("blocks", []):
        if block.get("type") == "display_math":
            yield block["latex"]


def iter_asset_ids(rt: dict | None) -> Iterator[str]:
    for block in (rt or {}).get("blocks", []):
        if block.get("type") in ("image", "diagram") and block.get("asset_id"):
            yield block["asset_id"]


def is_empty(rt: dict | None) -> bool:
    for block in (rt or {}).get("blocks", []):
        t = block.get("type")
        if t in ("display_math", "image", "diagram", "table", "list"):
            return False
        if t == "paragraph" and any(
            (s.get("text") or s.get("latex") or "").strip() for s in block.get("spans", [])
        ):
            return False
    return True


def to_plain_text(rt: dict | None) -> str:
    """Searchable text: words + raw LaTeX (for display_id/LaTeX-literal search)."""
    out: list[str] = []
    for block in (rt or {}).get("blocks", []):
        t = block.get("type")
        if t == "display_math":
            out.append(block["latex"])
        elif t in ("image", "diagram"):
            out.append(block.get("alt", ""))
    for span in iter_spans(rt):
        out.append(span.get("text") or span.get("latex") or "")
    return " ".join(x for x in out if x)


_LATEX_NOISE = re.compile(r"\\(left|right|displaystyle|,|;|!|quad|qquad)|\s+")


def normalize_for_dedup(text: str) -> str:
    """Normalisation used *only* for duplicate-candidate signals, never to rewrite content."""
    t = _LATEX_NOISE.sub("", text)
    t = t.replace("\\geqslant", "\\geq").replace("\\leqslant", "\\leq").replace("\\ge", "\\geq")
    t = t.replace("，", ",").replace("。", ".").replace("：", ":").replace("（", "(").replace("）", ")")
    return t


def walk(obj: Any) -> Iterator[Any]:
    yield obj
    if isinstance(obj, dict):
        for v in obj.values():
            yield from walk(v)
    elif isinstance(obj, list):
        for v in obj:
            yield from walk(v)

"""Safe math-input parser (docs/06 §3 security).

* Never calls eval/exec/sympify/parse_expr on user text.
* Whitelisted tokens, functions and symbols only; bounded length, depth and node count.
* Produces our own AST first, so we can record domain constraints (denominators, log/sqrt
  arguments, tan poles) *before* SymPy auto-simplifies e.g. x/x → 1.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from fractions import Fraction

import sympy as sp

MAX_LEN = 500
MAX_DEPTH = 40
MAX_NODES = 400
MAX_INT_EXPONENT = 400

FUNCTIONS = {
    "sin": sp.sin, "cos": sp.cos, "tan": sp.tan, "cot": sp.cot, "sec": sp.sec, "csc": sp.csc,
    "arcsin": sp.asin, "arccos": sp.acos, "arctan": sp.atan,
    "asin": sp.asin, "acos": sp.acos, "atan": sp.atan,
    "ln": sp.log, "log": sp.log, "lg": None, "exp": sp.exp, "sqrt": sp.sqrt, "abs": sp.Abs,
}
CONSTANTS = {"pi": sp.pi, "e": sp.E, "oo": sp.oo, "inf": sp.oo}


class MathInputError(ValueError):
    def __init__(self, code: str, message: str):
        super().__init__(message)
        self.code = code
        self.message = message


# ─────────────────────────── LaTeX / unicode normalisation ───────────────────────────
def _replace_braced_command(s: str, cmd: str, nargs: int, fmt) -> str:
    """Replace \\cmd{a}{b} (with nested braces) using fmt(*args)."""
    out = []
    i = 0
    needle = "\\" + cmd
    while True:
        j = s.find(needle, i)
        if j < 0:
            out.append(s[i:])
            break
        k = j + len(needle)
        if k < len(s) and s[k].isalpha():  # e.g. \frac vs \fracture — not ours
            out.append(s[i:k])
            i = k
            continue
        out.append(s[i:j])
        args = []
        opt = None
        while k < len(s) and s[k] == " ":
            k += 1
        if k < len(s) and s[k] == "[" and cmd == "sqrt":
            end = s.find("]", k)
            if end < 0:
                raise MathInputError("INVALID_MATH_INPUT", "unterminated [")
            opt = s[k + 1 : end]
            k = end + 1
        for _ in range(nargs):
            while k < len(s) and s[k] == " ":
                k += 1
            if k >= len(s):
                raise MathInputError("INVALID_MATH_INPUT", f"\\{cmd} missing argument")
            if s[k] != "{":  # \sqrt2 or \frac12 single-token shorthand
                args.append(s[k])
                k += 1
                continue
            depth = 0
            start = k
            while k < len(s):
                if s[k] == "{":
                    depth += 1
                elif s[k] == "}":
                    depth -= 1
                    if depth == 0:
                        break
                k += 1
            if depth != 0:
                raise MathInputError("INVALID_MATH_INPUT", "unbalanced braces")
            args.append(s[start + 1 : k])
            k += 1
        out.append(fmt(*args) if opt is None else fmt(*args, opt=opt))
        i = k
    return "".join(out)


def normalize_input(text: str) -> str:
    s = text.strip()
    if not s:
        raise MathInputError("INVALID_MATH_INPUT", "empty input")
    if len(s) > MAX_LEN:
        raise MathInputError("INVALID_MATH_INPUT", "input too long")
    # A leading "f'(x)=" / "y=" label is accepted and ignored.
    s = re.sub(r"^\s*[A-Za-z](?:'|\\prime)*\s*(\(\s*[A-Za-z]\s*\))?\s*=\s*", "", s)
    s = s.replace("\\dfrac", "\\frac").replace("\\tfrac", "\\frac")
    for _ in range(10):
        if "\\frac" not in s:
            break
        s = _replace_braced_command(s, "frac", 2, lambda a, b: f"(({a})/({b}))")
    s = _replace_braced_command(
        s, "sqrt", 1, lambda a, opt=None: f"sqrt({a})" if opt is None else f"(({a})^(1/({opt})))"
    )
    s = re.sub(r"\\(mathrm|operatorname|text)\{([A-Za-z]+)\}", r"\2", s)
    replacements = [
        ("\\left", ""), ("\\right", ""), ("\\cdot", "*"), ("\\times", "*"), ("\\div", "/"),
        ("\\pi", " pi "), ("\\infty", " oo "), ("\\ln", " ln "), ("\\log", " log "),
        ("\\exp", " exp "), ("\\arcsin", " arcsin "), ("\\arccos", " arccos "), ("\\arctan", " arctan "),
        ("\\sin", " sin "), ("\\cos", " cos "), ("\\tan", " tan "), ("\\cot", " cot "),
        ("\\,", " "), ("\\;", " "), ("\\!", ""), ("\\ ", " "),
        ("×", "*"), ("·", "*"), ("÷", "/"), ("−", "-"), ("π", " pi "), ("∞", " oo "), ("√", "sqrt"),
        ("（", "("), ("）", ")"), ("，", ","), ("**", "^"),
    ]
    for a, b in replacements:
        s = s.replace(a, b)
    s = s.replace("{", "(").replace("}", ")")
    if "\\" in s:
        cmd = re.search(r"\\[A-Za-z]*", s)
        raise MathInputError("INVALID_MATH_INPUT", f"unsupported command {cmd.group(0) if cmd else '\\'}")
    return s


# ─────────────────────────── tokenizer ───────────────────────────
_TOKEN_RE = re.compile(r"\s*(?:(\d+(?:\.\d+)?|\.\d+)|([A-Za-z]+)|(\^|\+|-|\*|/|\(|\)|,|\||!))")


@dataclass
class Tok:
    kind: str  # num / name / op / end
    value: str


def tokenize(s: str, variables: set[str]) -> list[Tok]:
    toks: list[Tok] = []
    pos = 0
    s = s.rstrip()
    while pos < len(s):
        m = _TOKEN_RE.match(s, pos)
        if not m or m.end() == pos:
            raise MathInputError("INVALID_MATH_INPUT", f"unexpected character {s[pos]!r}")
        num, name, op = m.groups()
        if num is not None:
            toks.append(Tok("num", num))
        elif name is not None:
            toks.extend(_split_name(name, variables))
        else:
            toks.append(Tok("op", op))
        pos = m.end()
    toks.append(Tok("end", ""))
    return toks


def _split_name(name: str, variables: set[str]) -> list[Tok]:
    """Split a letter run greedily into known functions/constants/variables (implicit products)."""
    known = sorted(set(FUNCTIONS) | set(CONSTANTS) | {v for v in variables if len(v) > 1}, key=len, reverse=True)
    out: list[Tok] = []
    i = 0
    while i < len(name):
        for k in known:
            if name.startswith(k, i):
                out.append(Tok("name", k))
                i += len(k)
                break
        else:
            out.append(Tok("name", name[i]))
            i += 1
    return out


# ─────────────────────────── AST + parser ───────────────────────────
# Node = tuple. ('num', Fraction) ('sym', str) ('const', str) ('neg', n) ('add'|'sub'|'mul'|'div'|'pow', a, b)
# ('call', fname, arg) ('fact', n)


@dataclass
class Parser:
    toks: list[Tok]
    variables: set[str]
    allow_unknown: bool = False
    i: int = 0
    nodes: int = 0
    used_symbols: set[str] = field(default_factory=set)

    def peek(self) -> Tok:
        return self.toks[self.i]

    def take(self) -> Tok:
        t = self.toks[self.i]
        self.i += 1
        return t

    def expect(self, value: str) -> None:
        t = self.take()
        if t.value != value:
            raise MathInputError("INVALID_MATH_INPUT", f"expected {value!r}")

    def node(self, *n):
        self.nodes += 1
        if self.nodes > MAX_NODES:
            raise MathInputError("INVALID_MATH_INPUT", "expression too large")
        return n

    def parse(self):
        n = self.expr(0)
        if self.peek().kind != "end":
            raise MathInputError("INVALID_MATH_INPUT", f"unexpected {self.peek().value!r}")
        return n

    def expr(self, depth: int, stop_bar: bool = False):
        if depth > MAX_DEPTH:
            raise MathInputError("INVALID_MATH_INPUT", "expression nested too deeply")
        n = self.term(depth, stop_bar)
        while self.peek().value in ("+", "-"):
            op = self.take().value
            r = self.term(depth, stop_bar)
            n = self.node("add" if op == "+" else "sub", n, r)
        return n

    def _starts_primary(self, t: Tok, stop_bar: bool) -> bool:
        if t.kind in ("num", "name"):
            return True
        return t.value == "(" or (t.value == "|" and not stop_bar)

    def term(self, depth: int, stop_bar: bool):
        n = self.unary(depth, stop_bar)
        while True:
            t = self.peek()
            if t.value in ("*", "/"):
                self.take()
                r = self.unary(depth, stop_bar)
                n = self.node("mul" if t.value == "*" else "div", n, r)
            elif self._starts_primary(t, stop_bar):  # implicit multiplication: 2x, x(x+1), 2sin x
                r = self.power(depth, stop_bar)
                n = self.node("mul", n, r)
            else:
                return n

    def unary(self, depth: int, stop_bar: bool):
        t = self.peek()
        if t.value == "-":
            self.take()
            return self.node("neg", self.unary(depth + 1, stop_bar))
        if t.value == "+":
            self.take()
            return self.unary(depth + 1, stop_bar)
        return self.power(depth, stop_bar)

    def power(self, depth: int, stop_bar: bool):
        base = self.postfix(depth, stop_bar)
        if self.peek().value == "^":
            self.take()
            exp = self.unary(depth + 1, stop_bar)  # right-assoc, allows x^-1
            return self.node("pow", base, exp)
        return base

    def postfix(self, depth: int, stop_bar: bool):
        n = self.primary(depth, stop_bar)
        while self.peek().value == "!":
            self.take()
            n = self.node("fact", n)
        return n

    def primary(self, depth: int, stop_bar: bool):
        t = self.take()
        if t.kind == "num":
            return self.node("num", Fraction(t.value))
        if t.value == "(":
            n = self.expr(depth + 1)
            self.expect(")")
            return n
        if t.value == "|":
            n = self.expr(depth + 1, stop_bar=True)
            self.expect("|")
            return self.node("call", "abs", n)
        if t.kind == "name":
            name = t.value
            if name in FUNCTIONS:
                if FUNCTIONS[name] is None:
                    raise MathInputError("INVALID_MATH_INPUT", f"function {name} not supported; use log")
                # optional power on function: sin^2 x
                fpow = None
                if self.peek().value == "^":
                    self.take()
                    fpow = self.postfix(depth + 1, stop_bar)
                if self.peek().value == "(":
                    self.take()
                    arg = self.expr(depth + 1)
                    self.expect(")")
                else:  # sin x, ln x  — binds to the next power term
                    arg = self.power(depth + 1, stop_bar)
                n = self.node("call", name, arg)
                return self.node("pow", n, fpow) if fpow is not None else n
            if name in CONSTANTS and name not in self.variables:
                return self.node("const", name)
            if name in self.variables or self.allow_unknown:
                self.used_symbols.add(name)
                return self.node("sym", name)
            raise MathInputError("UNKNOWN_SYMBOL", f"unknown symbol {name!r}")
        raise MathInputError("INVALID_MATH_INPUT", f"unexpected {t.value or 'end of input'!r}")


def parse(text: str, variables: set[str], allow_unknown: bool = False):
    s = normalize_input(text)
    p = Parser(tokenize(s, variables), variables, allow_unknown)
    ast = p.parse()
    return ast, p.used_symbols


# ─────────────────────────── AST → SymPy, domain constraints ───────────────────────────
def make_symbols(assumptions: dict[str, str]) -> dict[str, sp.Symbol]:
    flags = {
        "real": {"real": True},
        "positive": {"positive": True},
        "negative": {"negative": True},
        "nonnegative": {"nonnegative": True},
        "nonzero": {"real": True, "nonzero": True},
        "integer": {"integer": True},
        "positive_integer": {"integer": True, "positive": True},
    }
    return {name: sp.Symbol(name, **flags.get(kind, {"real": True})) for name, kind in assumptions.items()}


@dataclass
class Converted:
    expr: sp.Expr
    constraints: list[tuple[str, sp.Expr]]  # ('nonzero'|'positive'|'nonneg', expr)


def to_sympy(ast, symbols: dict[str, sp.Symbol]) -> Converted:
    constraints: list[tuple[str, sp.Expr]] = []

    def conv(n) -> sp.Expr:
        kind = n[0]
        if kind == "num":
            return sp.Rational(n[1].numerator, n[1].denominator)
        if kind == "sym":
            return symbols.get(n[1]) or sp.Symbol(n[1], real=True)
        if kind == "const":
            return CONSTANTS[n[1]]
        if kind == "neg":
            return -conv(n[1])
        if kind in ("add", "sub", "mul"):
            a, b = conv(n[1]), conv(n[2])
            return a + b if kind == "add" else a - b if kind == "sub" else a * b
        if kind == "div":
            a, b = conv(n[1]), conv(n[2])
            if b == 0:
                raise MathInputError("INVALID_MATH_INPUT", "division by zero")
            constraints.append(("nonzero", b))
            return a / b
        if kind == "pow":
            a, b = conv(n[1]), conv(n[2])
            if a.is_number and b.is_number and b.is_Integer and abs(int(b)) > MAX_INT_EXPONENT:
                raise MathInputError("INVALID_MATH_INPUT", "exponent too large")
            if a.is_Integer and b.is_Integer and abs(int(a)) > 1 and abs(int(b)) * len(str(abs(int(a)))) > 2000:
                raise MathInputError("INVALID_MATH_INPUT", "number too large")
            if b.is_number and b.is_negative:
                constraints.append(("nonzero", a))
            if b.is_Rational and not b.is_Integer and b.q % 2 == 0:
                constraints.append(("nonneg", a))
            elif not b.is_number:
                constraints.append(("positive", a)) if not a.is_number else None
            return a**b
        if kind == "fact":
            a = conv(n[1])
            if a.is_Integer and int(a) > 200:
                raise MathInputError("INVALID_MATH_INPUT", "factorial too large")
            return sp.factorial(a)
        if kind == "call":
            fname, arg = n[1], conv(n[2])
            if fname in ("ln", "log"):
                constraints.append(("positive", arg))
            elif fname == "sqrt":
                constraints.append(("nonneg", arg))
            elif fname in ("tan", "sec"):
                constraints.append(("nonzero", sp.cos(arg)))
            elif fname in ("cot", "csc"):
                constraints.append(("nonzero", sp.sin(arg)))
            return FUNCTIONS[fname](arg)
        raise MathInputError("INVALID_MATH_INPUT", f"bad node {kind}")

    return Converted(conv(ast), constraints)

"""Deterministic checkers (docs/06 §2 matrix). Pure functions; heavy ones run inside the sandbox.

Status vocabulary: accepted / rejected / partial are mathematical verdicts. invalid_response is a
format problem, pending_review means "could not decide" and is *never* reported as wrong.
"""
from __future__ import annotations

import json
import math
import random
import re
from dataclasses import asdict, dataclass, field
from decimal import Decimal, InvalidOperation
from fractions import Fraction
from typing import Any

import sympy as sp

from .mathparse import MathInputError, make_symbols, parse, to_sympy

GRADER_VERSION = "1.0.0"


@dataclass
class GradeResult:
    status: str
    score: str | None
    max_score: str
    result_code: str
    message: str
    details: dict = field(default_factory=dict)
    grader_name: str = "leetmath-deterministic"
    grader_version: str = GRADER_VERSION

    def to_dict(self) -> dict:
        return asdict(self)


def _q(d: Decimal) -> str:
    return str(d.quantize(Decimal("0.01")))


def accepted(max_score: Decimal, code="EQUIVALENT", msg="答案正确", **details) -> GradeResult:
    return GradeResult("accepted", _q(max_score), _q(max_score), code, msg, details)


def rejected(max_score: Decimal, code="NOT_EQUIVALENT", msg="答案与标准答案不等价", **details) -> GradeResult:
    return GradeResult("rejected", _q(Decimal(0)), _q(max_score), code, msg, details)


def invalid(max_score: Decimal, code="INVALID_MATH_INPUT", msg="无法解析输入格式", **details) -> GradeResult:
    return GradeResult("invalid_response", None, _q(max_score), code, msg, details)


def pending(max_score: Decimal, code="NEEDS_REVIEW", msg="无法自动判定，已转人工复核", **details) -> GradeResult:
    return GradeResult("pending_review", None, _q(max_score), code, msg, details)


# ─────────────────────────── choices ───────────────────────────
def _parse_choice_input(raw: str) -> list[str]:
    raw = raw.strip()
    if raw.startswith("["):
        try:
            val = json.loads(raw)
        except json.JSONDecodeError:
            return []
        return [str(v).strip() for v in val] if isinstance(val, list) else []
    return [p for p in re.split(r"[\s,，、;；]+", raw) if p]


def check_single_choice(spec: dict, raw: str, max_score: Decimal, option_ids: set[str]) -> GradeResult:
    sel = _parse_choice_input(raw)
    if len(sel) != 1 or (option_ids and sel[0] not in option_ids):
        return invalid(max_score, "INVALID_CHOICE", "请选择且仅选择一个有效选项")
    return accepted(max_score, "CORRECT_OPTION") if sel[0] == spec["expected"] else rejected(max_score, "WRONG_OPTION", "选项不正确")


def check_multiple_choice(spec: dict, raw: str, max_score: Decimal, option_ids: set[str]) -> GradeResult:
    sel = set(_parse_choice_input(raw))
    if not sel or (option_ids and not sel <= option_ids):
        return invalid(max_score, "INVALID_CHOICE", "请选择有效选项")
    correct = set(spec["expected"])
    if sel == correct:
        return accepted(max_score, "CORRECT_SET")
    if spec.get("partial_credit") == "proportional" and sel < correct:
        score = (max_score * len(sel) / len(correct)).quantize(Decimal("0.01"))
        return GradeResult("partial", _q(score), _q(max_score), "PARTIAL_SUBSET", "少选：部分得分", {})
    return rejected(max_score, "WRONG_SET", "选项集合不正确")


# ─────────────────────────── numbers ───────────────────────────
_INT_RE = re.compile(r"^[+-]?\d+$")
_FRAC_LATEX = re.compile(r"^([+-]?)\\d?frac\{\s*([+-]?\d+)\s*\}\{\s*([+-]?\d+)\s*\}$")


def parse_rational(raw: str) -> Fraction:
    s = raw.strip().replace(" ", "").replace("−", "-")
    m = _FRAC_LATEX.match(s)
    if m:
        sign, a, b = m.groups()
        s = f"{sign}{a}/{b}"
    if "/" in s:
        a, b = s.split("/", 1)
        if not _INT_RE.match(a) or not _INT_RE.match(b):
            raise MathInputError("INVALID_MATH_INPUT", "not a fraction")
        if int(b) == 0:
            raise MathInputError("INVALID_MATH_INPUT", "denominator is zero")
        return Fraction(int(a), int(b))
    try:
        d = Decimal(s)
    except InvalidOperation as e:
        raise MathInputError("INVALID_MATH_INPUT", "not a number") from e
    if not d.is_finite():
        raise MathInputError("INVALID_MATH_INPUT", "not finite")
    return Fraction(d)


def check_integer(spec: dict, raw: str, max_score: Decimal) -> GradeResult:
    s = raw.strip().replace(" ", "")
    if len(s) > 60 or not _INT_RE.match(s):
        return invalid(max_score, "NOT_AN_INTEGER", "请输入整数")
    return accepted(max_score) if int(s) == int(spec["expected"]) else rejected(max_score)


def check_rational(spec: dict, raw: str, max_score: Decimal) -> GradeResult:
    try:
        got = parse_rational(raw)
    except MathInputError as e:
        return invalid(max_score, e.code, "请输入整数、分数或有限小数")
    return accepted(max_score) if got == parse_rational(str(spec["expected"])) else rejected(max_score)


def check_decimal(spec: dict, raw: str, max_score: Decimal) -> GradeResult:
    try:
        got = parse_rational(raw)
    except MathInputError as e:
        return invalid(max_score, e.code, "请输入数值")
    exp = parse_rational(str(spec["expected"]))
    tol = spec.get("tolerance") or {}
    abs_tol = Fraction(Decimal(tol["abs"])) if tol.get("abs") else Fraction(0)
    rel_tol = Fraction(Decimal(tol["rel"])) if tol.get("rel") else Fraction(0)
    allowed = max(abs_tol, rel_tol * abs(exp))
    diff = abs(got - exp)
    if diff <= allowed:
        return accepted(max_score, "WITHIN_TOLERANCE" if allowed else "EQUIVALENT", tolerance=str(float(allowed)))
    return rejected(max_score, "OUT_OF_TOLERANCE" if allowed else "NOT_EQUIVALENT")


# ─────────────────────────── symbolic expressions ───────────────────────────
_SAMPLES = {
    "positive": [Fraction(1, 7), Fraction(1, 2), Fraction(1), Fraction(3, 2), Fraction(2), Fraction(27, 10), Fraction(5), Fraction(73, 10)],
    "nonnegative": [Fraction(0), Fraction(1, 3), Fraction(1), Fraction(5, 2), Fraction(4)],
    "negative": [Fraction(-1, 3), Fraction(-1), Fraction(-5, 2), Fraction(-4)],
    "nonzero": [Fraction(-3), Fraction(-1, 2), Fraction(1, 3), Fraction(1), Fraction(5, 2)],
    "integer": [Fraction(-3), Fraction(-1), Fraction(0), Fraction(1), Fraction(2), Fraction(5)],
    "positive_integer": [Fraction(1), Fraction(2), Fraction(3), Fraction(7)],
    "real": [Fraction(-31, 10), Fraction(-1), Fraction(0), Fraction(1, 2), Fraction(1), Fraction(27, 10), Fraction(4)],
}


def _satisfies(kind: str, v: sp.Expr) -> bool:
    if not v.is_real:
        return False
    return {
        "positive": v > 0, "negative": v < 0, "nonnegative": v >= 0, "nonzero": v != 0,
        "integer": v.is_integer, "positive_integer": bool(v.is_integer and v > 0), "real": True,
    }.get(kind, True)


def _num(e: sp.Expr, subs: dict) -> complex | None:
    try:
        v = complex(sp.N(e.subs(subs), 30))
    except (TypeError, ValueError, ZeroDivisionError, OverflowError):
        return None
    if math.isnan(v.real) or math.isnan(v.imag) or math.isinf(v.real) or math.isinf(v.imag):
        return None
    return v


def _defined(constraints: list[tuple[str, sp.Expr]], subs: dict) -> bool:
    for kind, e in constraints:
        v = _num(e, subs)
        if v is None or abs(v.imag) > 1e-12:
            return False
        r = v.real
        if kind == "nonzero" and abs(r) < 1e-12:
            return False
        if kind == "positive" and r <= 1e-15:
            return False
        if kind == "nonneg" and r < -1e-15:
            return False
    return True


def _singular_points(constraints, symbols: dict[str, sp.Symbol], base: dict) -> list[dict]:
    """Points where a constraint expression hits its boundary (zeros of denominators etc.)."""
    pts: list[dict] = []
    for _kind, e in constraints:
        free = [s for s in e.free_symbols if s in symbols.values()]
        for sym in free[:2]:
            others = {k: v for k, v in base.items() if k != sym}
            try:
                sol = sp.solveset(sp.Eq(e.subs(others), 0), sym, domain=sp.S.Reals)
            except Exception:  # noqa: BLE001 — solver limitations are non-fatal
                continue
            cands: list[sp.Expr] = []
            if isinstance(sol, sp.FiniteSet):
                cands = list(sol)[:6]
            elif isinstance(sol, sp.Union):
                for a in sol.args:
                    if isinstance(a, sp.FiniteSet):
                        cands += list(a)[:3]
                    elif isinstance(a, sp.ImageSet):
                        lam = a.lamda
                        cands += [lam(n) for n in (-1, 0, 1)]
            elif isinstance(sol, sp.ImageSet):
                cands = [sol.lamda(n) for n in (-1, 0, 1)]
            for c in cands:
                if c.free_symbols:
                    continue
                p = dict(base)
                p[sym] = c
                pts.append(p)
    return pts


def _sample_points(symbols: dict[str, sp.Symbol], assumptions: dict[str, str], n: int, seed: int) -> list[dict]:
    rng = random.Random(seed)
    names = sorted(symbols)
    pts = []
    for i in range(n):
        p = {}
        for name in names:
            pool = _SAMPLES.get(assumptions.get(name, "real"), _SAMPLES["real"])
            v = pool[(i + rng.randrange(len(pool))) % len(pool)]
            p[symbols[name]] = sp.Rational(v.numerator, v.denominator)
        pts.append(p)
    return pts


def _equal_symbolic(diff: sp.Expr) -> bool | None:
    try:
        for f in (lambda d: d, sp.simplify, lambda d: sp.simplify(sp.expand_log(d)), sp.trigsimp,
                  lambda d: sp.simplify(sp.expand(sp.powsimp(d)))):
            r = f(diff)
            if r == 0:
                return True
            if r.is_number and r.is_zero is False:
                return False
    except Exception:  # noqa: BLE001
        return None
    return None


def check_expression(spec: dict, raw: str, max_score: Decimal) -> GradeResult:
    assumptions: dict[str, str] = dict(spec.get("assumptions") or {})
    variables = set(assumptions) | set(spec.get("variables") or [])
    for v in variables:
        assumptions.setdefault(v, "real")
    symbols = make_symbols(assumptions)
    expected_src = spec.get("canonical_expr") or spec.get("expected")
    try:
        exp_ast, _ = parse(str(expected_src), variables)
        E = to_sympy(exp_ast, symbols)
    except MathInputError as e:
        return GradeResult("engine_error", None, _q(max_score), "BAD_ANSWER_SPEC", f"standard answer unparsable: {e.message}")
    try:
        resp_ast, _ = parse(raw, variables)
        R = to_sympy(resp_ast, symbols)
    except MathInputError as e:
        return invalid(max_score, e.code, f"格式解析失败：{e.message}")

    eq = _equal_symbolic(sp.simplify(R.expr - E.expr))
    samples = _sample_points(symbols, assumptions, 14, seed=7)
    probes = samples + _singular_points(R.constraints + E.constraints, symbols, samples[0] if samples else {})
    domain_mismatch = None
    counterexample = None
    for p in probes:
        if not all(_satisfies(assumptions.get(str(s), "real"), v) for s, v in p.items()):
            continue
        dR, dE = _defined(R.constraints, p), _defined(E.constraints, p)
        if dR != dE and domain_mismatch is None:
            domain_mismatch = {str(k): str(v) for k, v in p.items()}
        if dR and dE and counterexample is None and eq is not True:
            a, b = _num(R.expr, p), _num(E.expr, p)
            if a is not None and b is not None and abs(a - b) > 1e-9 * (1 + abs(b)):
                counterexample = {str(k): str(v) for k, v in p.items()}
    details = {"assumptions": assumptions, "parser": "leetmath-rd-1"}
    if eq is True and domain_mismatch is None:
        return accepted(max_score, "EQUIVALENT", "答案正确（在题设条件下符号等价）", **details)
    if counterexample is not None:
        return rejected(max_score, "COUNTEREXAMPLE", "答案与标准答案不等价", **details)
    if eq is False:
        return rejected(max_score, "NOT_EQUIVALENT", "答案与标准答案不等价", **details)
    if domain_mismatch is not None:
        return pending(max_score, "DOMAIN_MISMATCH", "表达式定义域与标准答案不同，已转人工复核", **details)
    return pending(max_score, "INCONCLUSIVE", "无法自动证明等价，已转人工复核", **details)


# ─────────────────────────── intervals & finite sets ───────────────────────────
_EMPTY = {"∅", "\\emptyset", "\\varnothing", "emptyset", "{}", "空集"}
_REALS = {"R", "\\mathbb{R}", "ℝ", "(-oo,oo)", "(-∞,+∞)", "(-\\infty,+\\infty)"}


def _split_top(s: str, seps: tuple[str, ...]) -> list[str]:
    parts, depth, cur, i = [], 0, "", 0
    while i < len(s):
        ch = s[i]
        if ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth -= 1
        matched = next((sep for sep in seps if depth == 0 and s.startswith(sep, i)), None)
        if matched:
            parts.append(cur)
            cur = ""
            i += len(matched)
            continue
        cur += ch
        i += 1
    parts.append(cur)
    return [p.strip() for p in parts]


def _parse_interval_union(raw: str, variables: set[str], symbols) -> list[tuple]:
    s = raw.strip().replace(" ", "").replace("\\left", "").replace("\\right", "")
    s = re.sub(r"^[A-Za-z]\\in|^[A-Za-z]∈", "", s)
    if s in _EMPTY:
        return []
    if s in _REALS:
        return [(-sp.oo, sp.oo, True, True)]
    pieces = _split_top(s, ("\\cup", "∪", "U"))
    out = []
    for piece in pieces:
        if len(piece) < 5 or piece[0] not in "([" or piece[-1] not in ")]":
            raise MathInputError("INVALID_MATH_INPUT", "区间格式应为 (a,b] 等")
        inner = _split_top(piece[1:-1], (",",))
        if len(inner) != 2:
            raise MathInputError("INVALID_MATH_INPUT", "区间需要两个端点")
        ends = []
        for t in inner:
            t = t.replace("+", "", 1) if t.startswith("+") else t
            ends.append(to_sympy(parse(t, variables)[0], symbols).expr)
        lo, hi = ends
        lo_open, hi_open = piece[0] == "(", piece[-1] == ")"
        if (lo in (sp.oo, -sp.oo) and not lo_open) or (hi in (sp.oo, -sp.oo) and not hi_open):
            raise MathInputError("INVALID_MATH_INPUT", "无穷端点必须为开")
        out.append((lo, hi, lo_open, hi_open))
    return out


def _same(a: sp.Expr, b: sp.Expr) -> bool:
    if a in (sp.oo, -sp.oo) or b in (sp.oo, -sp.oo):
        return a == b
    return _equal_symbolic(sp.simplify(a - b)) is True


def _match_multiset(xs: list, ys: list, eq) -> bool:
    if len(xs) != len(ys):
        return False
    used = [False] * len(ys)
    for x in xs:
        for j, y in enumerate(ys):
            if not used[j] and eq(x, y):
                used[j] = True
                break
        else:
            return False
    return True


def check_interval(spec: dict, raw: str, max_score: Decimal) -> GradeResult:
    assumptions = dict(spec.get("assumptions") or {})
    variables = set(assumptions) | set(spec.get("variables") or [])
    symbols = make_symbols({v: assumptions.get(v, "real") for v in variables})
    exp = _parse_interval_union(str(spec["expected"]), variables, symbols)
    try:
        got = _parse_interval_union(raw, variables, symbols)
    except MathInputError as e:
        return invalid(max_score, e.code, e.message)
    if all(not x.free_symbols for iv in got + exp for x in iv[:2]):
        to_set = lambda ivs: sp.Union(*[sp.Interval(lo, hi, lo_o, hi_o) for lo, hi, lo_o, hi_o in ivs]) if ivs else sp.S.EmptySet  # noqa: E731
        A, B = to_set(got), to_set(exp)
        if A == B or (A.symmetric_difference(B)) == sp.S.EmptySet:
            return accepted(max_score)
        return rejected(max_score, "INTERVAL_MISMATCH", "区间不正确（注意端点与开闭）")
    ok = _match_multiset(got, exp, lambda x, y: x[2:] == y[2:] and _same(x[0], y[0]) and _same(x[1], y[1]))
    return accepted(max_score) if ok else rejected(max_score, "INTERVAL_MISMATCH", "区间不正确（注意端点与开闭）")


def check_finite_set(spec: dict, raw: str, max_score: Decimal) -> GradeResult:
    assumptions = dict(spec.get("assumptions") or {})
    variables = set(assumptions) | set(spec.get("variables") or [])
    symbols = make_symbols({v: assumptions.get(v, "real") for v in variables})
    solve_var = spec.get("solve_for")

    def elems(s: str) -> list[sp.Expr]:
        s = s.strip()
        if s in _EMPTY:
            return []
        if s.startswith("\\{") and s.endswith("\\}"):
            s = s[2:-2]
        elif s.startswith("{") and s.endswith("}"):
            s = s[1:-1]
        items = [p for p in _split_top(s.replace("或", ",").replace("，", ","), (",", ";")) if p]
        out = []
        for it in items:
            if solve_var:
                it = re.sub(rf"^{re.escape(solve_var)}\s*=", "", it)
            out.append(to_sympy(parse(it, variables - ({solve_var} if solve_var else set()))[0], symbols).expr)
        return out

    exp = elems(str(spec["expected"]))
    try:
        got = elems(raw)
    except MathInputError as e:
        return invalid(max_score, e.code, e.message)
    if len({sp.srepr(sp.nsimplify(g)) for g in got}) != len(got) and not spec.get("allow_repeats"):
        got = list({sp.srepr(g): g for g in got}.values())
    if _match_multiset(got, exp, _same):
        return accepted(max_score)
    missing = len(exp) - sum(1 for e in exp if any(_same(e, g) for g in got))
    extra = len(got) - sum(1 for g in got if any(_same(e, g) for e in exp))
    return rejected(max_score, "SET_MISMATCH", "解集不正确", missing=missing, extra=extra)


# ─────────────────────────── dispatcher ───────────────────────────
SANDBOXED = {"symbolic_equivalence", "interval_set", "finite_set"}


def run_checker(checker_type: str, spec: dict, raw: str, max_score: Decimal, option_ids: set[str] | None = None) -> GradeResult:
    option_ids = option_ids or set()
    if checker_type == "choice_exact":
        return check_single_choice(spec, raw, max_score, option_ids)
    if checker_type == "choice_set":
        return check_multiple_choice(spec, raw, max_score, option_ids)
    if checker_type == "integer_exact":
        return check_integer(spec, raw, max_score)
    if checker_type == "rational_exact":
        return check_rational(spec, raw, max_score)
    if checker_type == "decimal_tolerance":
        return check_decimal(spec, raw, max_score)
    if checker_type == "symbolic_equivalence":
        return check_expression(spec, raw, max_score)
    if checker_type == "interval_set":
        return check_interval(spec, raw, max_score)
    if checker_type == "finite_set":
        return check_finite_set(spec, raw, max_score)
    return pending(max_score, "MANUAL_GRADING", "此题型需人工批改")


def _sandbox_entry(payload: dict) -> dict[str, Any]:
    r = run_checker(payload["checker_type"], payload["spec"], payload["raw"], Decimal(payload["max_score"]), set(payload["option_ids"]))
    return r.to_dict()

"""Process-isolated execution for CAS work (docs/06 §3, docs/11 §3).

Each grading call forks a child with RLIMIT_AS / RLIMIT_CPU, no inherited sockets used, and a
wall-clock timeout. SymPy is not itself a sandbox; the parser never evaluates code, and this
process boundary bounds resource exhaustion (huge expressions, pathological simplify).
Production: run the same entrypoint inside a network-less container.
"""
from __future__ import annotations

import multiprocessing as mp
import os
import resource
from decimal import Decimal

from ..config import settings
from .checkers import GradeResult, _sandbox_entry, pending


def _child(conn, payload, mem_mb: int, cpu_s: int):  # pragma: no cover - runs in child
    try:
        resource.setrlimit(resource.RLIMIT_AS, (mem_mb * 1024 * 1024, mem_mb * 1024 * 1024))
        resource.setrlimit(resource.RLIMIT_CPU, (cpu_s, cpu_s + 1))
    except (ValueError, OSError):
        pass
    try:
        conn.send(("ok", _sandbox_entry(payload)))
    except MemoryError:
        conn.send(("err", "MEMORY_LIMIT"))
    except Exception as e:  # noqa: BLE001
        conn.send(("err", f"{type(e).__name__}"))
    finally:
        conn.close()
        os._exit(0)


def run_sandboxed(payload: dict, timeout_s: float | None = None) -> GradeResult:
    timeout_s = timeout_s or settings.grader_timeout_s
    max_score = Decimal(payload["max_score"])
    ctx = mp.get_context("fork")
    parent, child = ctx.Pipe(duplex=False)
    p = ctx.Process(
        target=_child, args=(child, payload, settings.grader_memory_mb, int(timeout_s) + 1), daemon=True
    )
    p.start()
    child.close()
    try:
        if parent.poll(timeout_s):
            kind, value = parent.recv()
        else:
            kind, value = "timeout", None
    except EOFError:
        kind, value = "err", "CRASHED"
    finally:
        if p.is_alive():
            p.kill()
        p.join(1)
        parent.close()
    if kind == "ok":
        return GradeResult(**value)
    if kind == "timeout":
        return pending(max_score, "MATH_PARSER_TIMEOUT", "判题超时，已转人工复核（不计为错误）")
    if value == "MEMORY_LIMIT":
        return pending(max_score, "RESOURCE_LIMIT", "表达式过于复杂，已转人工复核")
    return GradeResult("engine_error", None, str(max_score.quantize(Decimal("0.01"))), "GRADER_UNAVAILABLE",
                       "判题引擎异常（不计为错误）", {"reason": value})

"""Public grading facade: maps a part's answer spec + response to a GradeResult."""
from __future__ import annotations

from decimal import Decimal

from .checkers import SANDBOXED, GradeResult, invalid, pending, run_checker
from .sandbox import run_sandboxed

# Which checker types are valid per response_type (preflight uses this).
CHECKERS_FOR_RESPONSE = {
    "single_choice": {"choice_exact"},
    "multiple_choice": {"choice_set"},
    "integer": {"integer_exact"},
    "rational": {"rational_exact"},
    "decimal": {"decimal_tolerance"},
    "expression": {"symbolic_equivalence"},
    "interval": {"interval_set"},
    "set": {"finite_set"},
    "equation_set": {"finite_set"},
}
MANUAL_ONLY = {"proof", "derivation", "drawing", "short_text", "matrix", "vector"}


def grade(
    response_type: str,
    grading_mode: str,
    checker_type: str,
    spec: dict,
    raw_input: str,
    max_score: Decimal,
    option_ids: set[str] | None = None,
    sandbox: bool = True,
) -> GradeResult:
    if not isinstance(raw_input, str) or not raw_input.strip():
        return invalid(max_score, "EMPTY_RESPONSE", "答案不能为空")
    if len(raw_input) > 2000:
        return invalid(max_score, "INVALID_MATH_INPUT", "输入过长")
    if grading_mode in ("manual",) or response_type in MANUAL_ONLY or checker_type == "rubric_manual":
        return pending(max_score, "MANUAL_GRADING", "已提交，等待教师按评分点批改")
    if grading_mode == "practice_only":
        return pending(max_score, "PRACTICE_ONLY", "练习模式：不自动评分，请对照解析自查")
    if checker_type not in CHECKERS_FOR_RESPONSE.get(response_type, set()):
        return pending(max_score, "UNSUPPORTED_CHECKER", "不支持的判题配置，已转人工")
    if sandbox and checker_type in SANDBOXED:
        result = run_sandboxed(
            {
                "checker_type": checker_type,
                "spec": spec,
                "raw": raw_input,
                "max_score": str(max_score),
                "option_ids": sorted(option_ids or []),
            }
        )
    else:
        result = run_checker(checker_type, spec, raw_input, max_score, option_ids)
    if grading_mode == "hybrid" and result.status == "accepted":
        # hybrid: auto-accept the final answer, but steps still need teacher review for full marks
        result.details["hybrid"] = True
    return result

"""Content Contract v1: JSON Schema + semantic preflight + canonical hashing (docs/03 §8, docs/08 §4).

Issues are {code, severity, path, message}. severity="blocking" can never be waived;
"warning" may be overridden by a reviewer with a reason.
"""
from __future__ import annotations

import hashlib
import json
from decimal import Decimal
from functools import lru_cache
from pathlib import Path
from typing import Any

from jsonschema import Draft202012Validator, FormatChecker

from ..config import ROOT
from ..grading.engine import CHECKERS_FOR_RESPONSE, MANUAL_ONLY, grade
from .richtext import is_empty, iter_asset_ids, iter_latex, latex_issues, normalize_for_dedup, to_plain_text

SCHEMA_PATH = ROOT / "content-schema" / "v1" / "problem.schema.json"
NORMALIZER_VERSION = "math-normalizer-v1"
SUPPORTED_MAJOR = 1


@lru_cache(maxsize=1)
def _validator() -> Draft202012Validator:
    schema = json.loads(Path(SCHEMA_PATH).read_text(encoding="utf-8"))
    Draft202012Validator.check_schema(schema)
    return Draft202012Validator(schema, format_checker=FormatChecker())


def issue(code: str, path: str, message: str, severity: str = "blocking") -> dict:
    return {"code": code, "severity": severity, "path": path, "message": message}


def schema_issues(doc: Any) -> list[dict]:
    out = []
    for err in sorted(_validator().iter_errors(doc), key=lambda e: list(e.absolute_path)):
        path = "/" + "/".join(str(p) for p in err.absolute_path)
        out.append(issue("SCHEMA_VIOLATION", path, err.message[:300]))
    return out


def _dec(s: str) -> Decimal:
    return Decimal(str(s))


def preflight(doc: dict, known_assets: set[str] | None = None, run_golden: bool = True) -> list[dict]:
    """Full content check. Returns issues; any blocking issue prevents submit-for-review/publish."""
    issues = schema_issues(doc)
    if issues:
        return issues  # semantic checks assume structural validity
    rev = doc["revision"]
    asset_ids = {a["asset_id"] for a in doc.get("assets", [])} | (known_assets or set())

    def check_rt(rt: dict, path: str) -> None:
        for latex in iter_latex(rt):
            for msg in latex_issues(latex):
                issues.append(issue("LATEX_RENDER_FATAL", path, f"{msg}: {latex[:60]}"))
        for aid in iter_asset_ids(rt):
            if aid not in asset_ids:
                issues.append(issue("ASSET_MISSING", path, f"asset {aid} not found"))
        for i, block in enumerate(rt.get("blocks", [])):
            if block.get("type") == "display_math" and not block.get("alt_text"):
                issues.append(issue("MISSING_ALT", f"{path}/blocks/{i}", "display math has no alt_text", "warning"))
            if block.get("type") == "image" and not block.get("alt", "").strip():
                issues.append(issue("MISSING_ALT", f"{path}/blocks/{i}", "image has no alt text", "warning"))

    check_rt(rev["shared_statement"], "/revision/shared_statement")
    shared_empty = is_empty(rev["shared_statement"])

    parts = rev["parts"]
    orders = [p["display_order"] for p in parts]
    keys = [p["part_key"] for p in parts]
    if len(set(orders)) != len(orders):
        issues.append(issue("DUPLICATE_DISPLAY_ORDER", "/revision/parts", "display_order must be unique"))
    if len(set(keys)) != len(keys):
        issues.append(issue("DUPLICATE_PART_KEY", "/revision/parts", "part_key must be unique"))
    lids = [p.get("logical_part_id") for p in parts if p.get("logical_part_id")]
    if len(set(lids)) != len(lids):
        issues.append(issue("DUPLICATE_LOGICAL_PART", "/revision/parts", "logical_part_id must be unique"))

    any_content = not shared_empty
    for idx, part in enumerate(parts):
        pp = f"/revision/parts/{idx}"
        check_rt(part["prompt"], f"{pp}/prompt")
        if is_empty(part["prompt"]):
            if shared_empty:
                issues.append(issue("PART_EMPTY", f"{pp}/prompt", "part has no visible content"))
        else:
            any_content = True
        max_score = _dec(part["max_score"])
        if max_score <= 0:
            issues.append(issue("MAX_SCORE_NOT_POSITIVE", f"{pp}/max_score", "max_score must be > 0"))
        rtype = part["response_type"]
        spec = part["answer_spec"]
        mode = spec["grading_mode"]
        ctype = spec["checker_type"]
        rubric = part.get("rubric")

        if rubric:
            total = sum(_dec(c["max_points"]) for c in rubric["criteria"])
            if total != max_score:
                issues.append(issue("RUBRIC_SUM_MISMATCH", f"{pp}/rubric", f"rubric total {total} ≠ max_score {max_score}"))
            ids = [c["id"] for c in rubric["criteria"]]
            if len(set(ids)) != len(ids):
                issues.append(issue("RUBRIC_DUPLICATE_ID", f"{pp}/rubric", "criterion ids must be unique"))

        if rtype in ("single_choice", "multiple_choice"):
            opts = part.get("options") or []
            oids = [o["id"] for o in opts]
            if len(opts) < 2:
                issues.append(issue("CHOICE_OPTIONS_MISSING", f"{pp}/options", "choice parts need ≥2 options"))
            if len(set(oids)) != len(oids):
                issues.append(issue("CHOICE_DUPLICATE_ID", f"{pp}/options", "option ids must be unique"))
            for j, o in enumerate(opts):
                check_rt(o["content"], f"{pp}/options/{j}")
            exp = spec.get("expected")
            exp_set = set(exp) if isinstance(exp, list) else {exp}
            if not exp_set or not exp_set <= set(oids):
                issues.append(issue("CHOICE_EXPECTED_INVALID", f"{pp}/answer_spec/expected", "expected option(s) not among options"))
            if rtype == "single_choice" and isinstance(exp, list):
                issues.append(issue("CHOICE_EXPECTED_INVALID", f"{pp}/answer_spec/expected", "single choice expects one id"))

        if mode in ("automatic", "hybrid"):
            if rtype in MANUAL_ONLY:
                issues.append(issue("AUTO_GRADING_UNSUPPORTED", f"{pp}/answer_spec", f"{rtype} cannot be auto-graded in P0; use manual"))
            elif ctype not in CHECKERS_FOR_RESPONSE.get(rtype, set()):
                issues.append(issue("CHECKER_MISMATCH", f"{pp}/answer_spec/checker_type", f"{ctype} invalid for {rtype}"))
            elif "expected" not in spec and "canonical_expr" not in spec:
                issues.append(issue("ANSWER_MISSING", f"{pp}/answer_spec", "automatic grading needs an expected answer"))
            else:
                if rtype == "expression":
                    _check_assumptions(spec, pp, issues)
                if run_golden and not any(i["severity"] == "blocking" and i["path"].startswith(pp) for i in issues):
                    _golden(part, pp, issues)
        else:  # manual / practice_only
            if mode == "manual" and not rubric:
                issues.append(issue("RUBRIC_MISSING", f"{pp}/rubric", "manual grading requires a rubric"))

        sols = part.get("solutions") or []
        if not sols:
            issues.append(issue("NO_SOLUTION", f"{pp}/solutions", "part has no worked solution", "warning"))
        for j, s in enumerate(sols):
            if s.get("review_state") not in ("reviewed", "verified"):
                issues.append(issue("SOLUTION_UNREVIEWED", f"{pp}/solutions/{j}", "solution not yet reviewed", "warning"))
            for k, step in enumerate(s["steps"]):
                for msg in latex_issues(step):
                    issues.append(issue("LATEX_RENDER_FATAL", f"{pp}/solutions/{j}/steps/{k}", msg))

        steps = part.get("reasoning_steps") or []
        if steps:
            total = sum(_dec(s["max_points"]) for s in steps)
            if total != max_score:
                issues.append(issue("STEP_POINTS_MISMATCH", f"{pp}/reasoning_steps", f"step points {total} ≠ max_score {max_score}"))
            sorders = [s["order"] for s in steps]
            skeys = [s["semantic_key"] for s in steps]
            if len(set(sorders)) != len(sorders) or len(set(skeys)) != len(skeys):
                issues.append(issue("STEP_DUPLICATE", f"{pp}/reasoning_steps", "step order/semantic_key must be unique"))
            for k, s in enumerate(steps):
                for msg in latex_issues(s["reference_latex"]):
                    issues.append(issue("LATEX_RENDER_FATAL", f"{pp}/reasoning_steps/{k}", msg))

    if not any_content:
        issues.append(issue("STATEMENT_EMPTY", "/revision", "problem has no visible content"))

    md = rev["content_metadata"]
    if "platform_difficulty" not in md:
        issues.append(issue("NO_DIFFICULTY", "/revision/content_metadata", "no platform difficulty", "warning"))
    if not md.get("curriculum_mappings"):
        issues.append(issue("NO_KNOWLEDGE", "/revision/content_metadata", "no knowledge mapping", "warning"))
    if md.get("verified_exam") and not (md.get("verified_by") and md.get("verification_ref")):
        issues.append(issue("EXAM_UNVERIFIED", "/revision/content_metadata", "verified_exam requires verified_by + verification_ref"))
    return issues


def _check_assumptions(spec: dict, pp: str, issues: list) -> None:
    from ..grading.mathparse import MathInputError, parse

    src = spec.get("canonical_expr") or spec.get("expected")
    declared = set(spec.get("assumptions") or {}) | set(spec.get("variables") or [])
    try:
        _, used = parse(str(src), declared, allow_unknown=True)
    except MathInputError as e:
        issues.append(issue("ANSWER_UNPARSABLE", f"{pp}/answer_spec", e.message))
        return
    missing = used - declared
    if missing:
        issues.append(issue("ASSUMPTIONS_INCOMPLETE", f"{pp}/answer_spec/assumptions",
                            f"declare domain assumptions for: {', '.join(sorted(missing))}"))


def _golden(part: dict, pp: str, issues: list) -> None:
    """The expected answer must grade as accepted against itself, plus any declared golden cases."""
    spec = part["answer_spec"]
    ms = _dec(part["max_score"])
    oids = {o["id"] for o in part.get("options") or []}
    exp = spec.get("expected", spec.get("canonical_expr"))
    self_input = ",".join(exp) if isinstance(exp, list) else str(exp)
    cases = [{"input": self_input, "expect": "accepted"}] + list(spec.get("golden_cases") or [])
    for case in cases:
        r = grade(part["response_type"], spec["grading_mode"], spec["checker_type"], spec, case["input"], ms, oids)
        if r.status != case["expect"]:
            issues.append(issue("GOLDEN_CASE_FAILED", f"{pp}/answer_spec",
                                f"input {case['input']!r}: expected {case['expect']}, got {r.status} ({r.result_code})"))


# ─────────────────────────── hashing ───────────────────────────
def canonical_json(obj: Any) -> str:
    return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def sha256_text(s: str | bytes) -> str:
    return hashlib.sha256(s.encode("utf-8") if isinstance(s, str) else s).hexdigest()


_PART_HASH_FIELDS = ("part_key", "display_order", "response_type", "max_score", "prompt", "options",
                     "answer_spec", "rubric", "solutions", "reasoning_steps")


def content_hash(doc: dict) -> str:
    """Hash of the semantic content of a revision (ids, statuses and provenance excluded)."""
    rev = doc["revision"]
    payload = {
        "locale": rev["locale"],
        "title": rev["title"],
        "shared_statement": rev["shared_statement"],
        "parts": [{k: p.get(k) for k in _PART_HASH_FIELDS} for p in sorted(rev["parts"], key=lambda p: p["display_order"])],
        "assets": sorted(a["sha256"] for a in doc.get("assets", [])),
    }
    return sha256_text(canonical_json(payload))


def statement_fingerprint(doc: dict) -> str:
    """Text used for L1/L2 duplicate signals: statement + part prompts (no answers, no ids)."""
    rev = doc["revision"]
    texts = [to_plain_text(rev["shared_statement"])]
    for p in sorted(rev["parts"], key=lambda p: p["display_order"]):
        texts.append(to_plain_text(p["prompt"]))
    return normalize_for_dedup("|".join(texts))


def schema_major(doc: dict) -> int | None:
    try:
        return int(str(doc.get("schema_version", "")).split(".")[0])
    except ValueError:
        return None

