"""Source adapters (docs/05 §2). Adapters only *parse + normalise* to Contract v1 — they never publish.

New sources add an adapter + config; core tables never change.
"""
from __future__ import annotations

import csv
import io
import json
import re
from dataclasses import dataclass, field
from typing import Iterator

from ..content.contract import NORMALIZER_VERSION, sha256_text


class AdapterError(Exception):
    def __init__(self, stage: str, code: str, message: str):
        super().__init__(message)
        self.stage, self.code, self.message = stage, code, message


@dataclass
class RawRow:
    row_no: int
    raw: bytes
    key_hint: str | None = None


@dataclass
class IntakeRecord:
    external_id: str
    external_revision: str
    doc: dict
    warnings: list[str] = field(default_factory=list)


# ─────────────────────────── rich-text helpers ───────────────────────────
_DOLLAR = re.compile(r"\$([^$]+)\$")
_MATHY = re.compile(r"([A-Za-z0-9\\^_{}()'+\-=<>|.,\s]*\\[A-Za-z]+[A-Za-z0-9\\^_{}()'+\-=<>|.\s]*|[A-Za-z]\([A-Za-z]\)'?|[A-Za-z]'\([A-Za-z]\))")


def text_to_richtext(text: str) -> dict:
    """'已知 $f(x)=x^2$ 求…' → paragraph spans. Without $…$, LaTeX-looking runs become inline math."""
    spans = []
    if "$" in text:
        pos = 0
        for m in _DOLLAR.finditer(text):
            if m.start() > pos:
                spans.append({"type": "text", "text": text[pos:m.start()]})
            spans.append({"type": "inline_math", "latex": m.group(1).strip()})
            pos = m.end()
        if pos < len(text):
            spans.append({"type": "text", "text": text[pos:]})
    else:
        pos = 0
        for m in _MATHY.finditer(text):
            seg = m.group(0).strip()
            if not seg:
                continue
            if m.start() > pos:
                spans.append({"type": "text", "text": text[pos:m.start()]})
            spans.append({"type": "inline_math", "latex": seg})
            pos = m.end()
        if pos < len(text):
            spans.append({"type": "text", "text": text[pos:]})
    spans = [sp for sp in spans if sp.get("text", sp.get("latex", "")).strip()]
    return {"blocks": [{"type": "paragraph", "spans": spans}]} if spans else {"blocks": []}


def _pseudo_revision(raw: bytes) -> str:
    return "h:" + sha256_text(raw)[:16]


# ─────────────────────────── adapters ───────────────────────────
class ContractJsonlAdapter:
    """Each line is a full Content Contract v1 document (our own / partner native format)."""

    adapter_version = "contract-jsonl-v1"

    def rows(self, data: bytes) -> Iterator[RawRow]:
        for i, line in enumerate(data.decode("utf-8").splitlines(), start=1):
            if line.strip():
                yield RawRow(i, line.encode("utf-8"))

    def parse(self, row: RawRow, source_code: str) -> IntakeRecord:
        try:
            doc = json.loads(row.raw)
        except json.JSONDecodeError as e:
            raise AdapterError("parse", "PARSE_FAILED", f"invalid JSON: {e.msg}") from e
        if not isinstance(doc, dict):
            raise AdapterError("parse", "PARSE_FAILED", "record is not an object")
        refs = doc.get("source_record_refs") or []
        ref = next((r for r in refs if r.get("source_code") == source_code), None)
        if ref is None:
            raise AdapterError("normalize", "NORMALIZE_FAILED", f"no source_record_ref for source {source_code}")
        for k in ("id",):
            (doc.get("problem") or {}).pop(k, None)
            (doc.get("revision") or {}).pop(k, None)
        for p in (doc.get("revision") or {}).get("parts", []) or []:
            p.pop("id", None)
            p.pop("logical_part_id", None)
        (doc.get("problem") or {}).pop("display_id", None)
        (doc.get("revision") or {}).pop("status", None)
        return IntakeRecord(str(ref["external_id"]), str(ref.get("external_revision") or _pseudo_revision(row.raw)), doc)


class DemoJsonlAdapter:
    """docs/examples/demo-source.jsonl shape: {external_id, version, title, stem_latex, parts[{key, question}]}.

    The format carries no answers → parts become practice-only drafts that editors must complete.
    """

    adapter_version = "demo-jsonl-v1"

    def rows(self, data: bytes) -> Iterator[RawRow]:
        yield from ContractJsonlAdapter().rows(data)

    def parse(self, row: RawRow, source_code: str) -> IntakeRecord:
        try:
            rec = json.loads(row.raw)
            ext, ver, title, parts = rec["external_id"], str(rec.get("version", "")), rec["title"], rec["parts"]
        except (json.JSONDecodeError, KeyError, TypeError) as e:
            raise AdapterError("parse", "PARSE_FAILED", f"bad demo record: {e}") from e
        if not parts:
            raise AdapterError("normalize", "NORMALIZE_FAILED", "record has no parts")
        stem = rec.get("stem_latex")
        doc = {
            "schema_version": "1.0.0",
            "problem": {"grade_band": rec.get("grade_band", "senior_high"), "subject": "mathematics"},
            "revision": {
                "locale": rec.get("locale", "zh-CN"),
                "title": title,
                "shared_statement": {"blocks": [{"type": "display_math", "latex": stem}]} if stem else {"blocks": []},
                "content_metadata": {"region_hints": rec.get("region_hints", ["CN-SH"]), "import_placeholder_scores": True},
                "parts": [
                    {
                        "part_key": str(p["key"]), "display_order": i, "response_type": "short_text",
                        "max_score": "1.00", "prompt": text_to_richtext(p["question"]),
                        "answer_spec": {"spec_version": 1, "grading_mode": "practice_only", "checker_type": "rubric_manual"},
                    }
                    for i, p in enumerate(parts, start=1)
                ],
            },
            "source_record_refs": [{"source_code": source_code, "external_id": ext, "external_revision": ver or _pseudo_revision(row.raw)}],
            "rights_policy_ref": "",
        }
        return IntakeRecord(ext, ver or _pseudo_revision(row.raw), doc,
                            ["answers missing: parts imported as practice_only with placeholder max_score 1.00"])


class CsvSimpleAdapter:
    """Partner CSV: one line per part; lines sharing external_id form one problem.

    Columns: external_id, version, title, grade_band, region, statement, part_key, prompt, response_type,
    max_score, checker_type, expected, assumptions(JSON), options(JSON {"A":"…"}), knowledge_code,
    difficulty, solution. Inline math uses $…$.
    """

    adapter_version = "csv-simple-v1"
    REQUIRED = {"external_id", "title", "part_key", "prompt", "response_type", "max_score"}

    def rows(self, data: bytes) -> Iterator[RawRow]:
        text = data.decode("utf-8-sig")
        reader = csv.DictReader(io.StringIO(text))
        missing = self.REQUIRED - set(reader.fieldnames or [])
        if missing:
            raise AdapterError("parse", "IMPORT_SCHEMA_MISMATCH", f"missing CSV columns: {sorted(missing)}")
        groups: dict[str, list[tuple[int, dict]]] = {}
        order: list[str] = []
        for line_no, rec in enumerate(reader, start=2):
            ext = (rec.get("external_id") or "").strip() or f"__line{line_no}"
            if ext not in groups:
                order.append(ext)
            groups.setdefault(ext, []).append((line_no, rec))
        for ext in order:
            lines = groups[ext]
            yield RawRow(lines[0][0], json.dumps([r for _, r in lines], ensure_ascii=False, sort_keys=True).encode("utf-8"), ext)

    def parse(self, row: RawRow, source_code: str) -> IntakeRecord:
        recs = json.loads(row.raw)
        first = recs[0]
        ext = (first.get("external_id") or "").strip()
        if not ext:
            raise AdapterError("parse", "PARSE_FAILED", "external_id is empty")
        parts = []
        try:
            for i, r in enumerate(recs, start=1):
                rtype = r["response_type"].strip()
                ctype = (r.get("checker_type") or "").strip()
                spec: dict = {"spec_version": 1, "grading_mode": "automatic" if ctype and ctype != "rubric_manual" else "manual",
                              "checker_type": ctype or "rubric_manual"}
                if r.get("expected"):
                    exp = r["expected"].strip()
                    spec["expected"] = [x.strip() for x in exp.split("|")] if rtype == "multiple_choice" else exp
                if r.get("assumptions"):
                    spec["assumptions"] = json.loads(r["assumptions"])
                part = {"part_key": r["part_key"].strip(), "display_order": i, "response_type": rtype,
                        "max_score": r["max_score"].strip(), "prompt": text_to_richtext(r["prompt"]), "answer_spec": spec}
                if r.get("options"):
                    opts = json.loads(r["options"])
                    part["options"] = [{"id": k, "content": text_to_richtext(v)} for k, v in opts.items()]
                if r.get("knowledge_code"):
                    part["knowledge_codes"] = [r["knowledge_code"].strip()]
                if r.get("solution"):
                    part["solutions"] = [{"type": "worked", "review_state": "unreviewed", "steps": [r["solution"]]}]
                if spec["grading_mode"] == "manual":
                    part["rubric"] = {"version": 1, "criteria": [{"id": f"P{i}-C1", "description": "按参考解答整体评分", "max_points": part["max_score"]}]}
                parts.append(part)
        except (KeyError, ValueError, AttributeError) as e:
            raise AdapterError("normalize", "NORMALIZE_FAILED", f"bad CSV value: {e}") from e
        md: dict = {"region_hints": [first["region"]] if first.get("region") else []}
        if (first.get("difficulty") or "").strip().isdigit():
            md["platform_difficulty"] = {"value": int(first["difficulty"]), "origin": f"source:{source_code}"}
        codes = sorted({c for p in parts for c in p.get("knowledge_codes", [])})
        if codes and first.get("curriculum_code") and first.get("release_code"):
            md["curriculum_mappings"] = [{"curriculum_code": first["curriculum_code"], "release_code": first["release_code"],
                                          "knowledge_code": c, "relation_type": "tested"} for c in codes]
        doc = {
            "schema_version": "1.0.0",
            "problem": {"grade_band": (first.get("grade_band") or "senior_high").strip(), "subject": "mathematics"},
            "revision": {"locale": "zh-CN", "title": first["title"].strip(),
                         "shared_statement": text_to_richtext(first.get("statement") or ""),
                         "content_metadata": md, "parts": parts},
            "source_record_refs": [{"source_code": source_code, "external_id": ext,
                                    "external_revision": (first.get("version") or "").strip() or _pseudo_revision(row.raw)}],
            "rights_policy_ref": "",
        }
        return IntakeRecord(ext, doc["source_record_refs"][0]["external_revision"], doc)


ADAPTERS = {a.adapter_version: a for a in (ContractJsonlAdapter(), DemoJsonlAdapter(), CsvSimpleAdapter())}
SUPPORTED_NORMALIZERS = {NORMALIZER_VERSION}

"""Phase 1.5 Reasoning Practice (docs/reasoning-practice/ALGORITHMS.md, algorithm v0-local).

Self-recall scores are *never* written to `evaluations`; they are subjective evidence only.
"""
from __future__ import annotations

import math
from datetime import datetime, timedelta, timezone
from decimal import Decimal
from zoneinfo import ZoneInfo

from sqlalchemy import func, select
from sqlalchemy.orm import Session

from ..models import (
    KnowledgeNode,
    KnowledgeSelfAssessment,
    LearningAttempt,
    Problem,
    ProblemRevision,
    ReasoningStep,
    RevisionPart,
    StepReviewEvent,
    StepReviewState,
    User,
    XpAward,
    utcnow,
)
from .catalog import public_revision
from .errors import ApiError

ALGORITHM_VERSION = "v0-local"
SCHEDULER_VERSION = "fixed-1-3-7"
GRADE = {"know": Decimal("1.0"), "fuzzy": Decimal("0.45"), "unsure": Decimal("0")}
INTERVAL_DAYS = {"know": 7, "fuzzy": 3, "unsure": 1}
PRIOR_ALPHA = PRIOR_BETA = 2.0
SELF_ASSESS_WEIGHT = 0.5


def _aware(dt: datetime) -> datetime:
    return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)


def _steps_for_revision(s: Session, rev: ProblemRevision) -> list[ReasoningStep]:
    out = []
    for part in rev.parts:
        out += s.scalars(select(ReasoningStep).where(ReasoningStep.revision_part_id == part.id)
                         .order_by(ReasoningStep.step_order)).all()
    return out


def practice_catalog(s: Session) -> list[dict]:
    out = []
    for p in s.scalars(select(Problem).order_by(Problem.display_id)):
        rev = public_revision(s, p)
        if rev is None:
            continue
        steps = _steps_for_revision(s, rev)
        if steps:
            out.append({"problem_id": p.id, "display_id": p.display_id, "slug": p.slug, "revision_id": rev.id,
                        "title": rev.title, "part_count": len(rev.parts), "step_count": len(steps),
                        "max_score": str(sum(Decimal(x.max_points) for x in steps)),
                        "difficulty": rev.platform_difficulty})
    return out


def start(s: Session, user: User, problem_revision_id: str | None, mode: str = "full") -> LearningAttempt:
    if mode == "full":
        rev = s.get(ProblemRevision, problem_revision_id) if problem_revision_id else None
        if rev is None or public_revision(s, s.get(Problem, rev.problem_id)) is not rev:
            raise ApiError("NOT_FOUND", "problem not available")
        steps = _steps_for_revision(s, rev)
        if not steps:
            raise ApiError("VALIDATION_FAILED", "this problem has no reasoning steps")
        att = LearningAttempt(user_id=user.id, problem_revision_id=rev.id, mode="full", card_ids=[x.id for x in steps])
    elif mode == "due":
        now = utcnow()
        states = s.scalars(select(StepReviewState).where(StepReviewState.user_id == user.id)
                           .order_by(StepReviewState.due_at)).all()
        chosen, seen_parts = [], set()
        for st in states:
            if _aware(st.due_at) > now:
                continue
            step = s.get(ReasoningStep, st.step_id)
            part = s.get(RevisionPart, step.revision_part_id)
            rev = s.get(ProblemRevision, part.problem_revision_id)
            if public_revision(s, s.get(Problem, rev.problem_id)) is not rev:
                continue  # retracted / rights-held / superseded content is hidden from review too
            if part.id in seen_parts:  # sibling burial: one card per part per session
                continue
            seen_parts.add(part.id)
            chosen.append(step.id)
            if len(chosen) >= 20:
                break
        if not chosen:
            raise ApiError("NOT_FOUND", "no cards are due")
        att = LearningAttempt(user_id=user.id, problem_revision_id=None, mode="due", card_ids=chosen)
    else:
        raise ApiError("VALIDATION_FAILED", "mode must be full or due")
    s.add(att)
    s.flush()
    return att


def _get_owned(s: Session, user: User, attempt_id: str) -> LearningAttempt:
    att = s.get(LearningAttempt, attempt_id)
    if att is None or att.user_id != user.id:
        raise ApiError("NOT_FOUND", "attempt not found")
    return att


def view(s: Session, user: User, attempt_id: str) -> dict:
    att = _get_owned(s, user, attempt_id)
    events = {e.step_id: e for e in s.scalars(select(StepReviewEvent).where(StepReviewEvent.attempt_id == att.id))}
    cards = []
    current_index = None
    for i, sid in enumerate(att.card_ids):
        st = s.get(ReasoningStep, sid)
        part = s.get(RevisionPart, st.revision_part_id)
        ev = events.get(sid)
        card = {"step_id": sid, "index": i, "part_key": part.part_key, "part_id": part.id, "order": st.step_order,
                "recall_cue": st.recall_cue, "max_points": str(st.max_points), "criticality": st.criticality,
                "knowledge_codes": st.knowledge_codes, "reviewed": ev is not None}
        if ev is not None:  # reference is revealed only after the student committed a rating
            card.update(rating=ev.rating, self_score=str(ev.self_score), reference_latex=st.reference_latex,
                        explanation=st.explanation)
        elif current_index is None:
            current_index = i
        cards.append(card)
    total = sum(Decimal(c["max_points"]) for c in cards)
    earned = sum(Decimal(c.get("self_score", "0")) for c in cards)
    codes = sorted({c for card in cards for c in card["knowledge_codes"]})
    assessed = {a.knowledge_code: a.level for a in s.scalars(select(KnowledgeSelfAssessment).where(KnowledgeSelfAssessment.attempt_id == att.id))}
    rev = s.get(ProblemRevision, att.problem_revision_id) if att.problem_revision_id else None
    return {
        "attempt_id": att.id, "mode": att.mode, "state": att.state, "algorithm_version": ALGORITHM_VERSION,
        "problem": None if rev is None else {"revision_id": rev.id, "title": rev.title, "shared_statement": rev.shared_statement,
                                             "parts": [{"id": p.id, "part_key": p.part_key, "prompt": p.prompt, "max_score": str(p.max_score)} for p in rev.parts]},
        "cards": cards, "current_index": current_index,
        "self_recall_score": str(earned), "self_recall_max": str(total),
        "score_label": "主观自评参考分（非正式数学成绩）",
        "knowledge_codes": codes, "knowledge_assessed": assessed,
    }


def review(s: Session, user: User, attempt_id: str, event_id: str, step_id: str, rating: str,
           revealed_before_rating: bool = False) -> dict:
    if rating not in GRADE:
        raise ApiError("VALIDATION_FAILED", "rating must be know / fuzzy / unsure")
    if not event_id or len(event_id) < 8:
        raise ApiError("VALIDATION_FAILED", "event_id (client UUID) required")
    att = _get_owned(s, user, attempt_id)
    prior = s.get(StepReviewEvent, event_id)
    if prior is not None:
        if prior.user_id != user.id or prior.step_id != step_id or prior.rating != rating or prior.attempt_id != att.id:
            raise ApiError("IDEMPOTENCY_CONFLICT", "event_id reused with different payload")
        return _review_result(s, prior, replayed=True, xp=0)
    if step_id not in att.card_ids:
        raise ApiError("VALIDATION_FAILED", "step is not part of this attempt")
    done = {e.step_id for e in s.scalars(select(StepReviewEvent).where(StepReviewEvent.attempt_id == att.id))}
    if step_id in done:
        raise ApiError("CONFLICT", "this step was already rated in this attempt (ratings are append-only)")
    idx = att.card_ids.index(step_id)
    if any(cid not in done for cid in att.card_ids[:idx]):
        raise ApiError("VALIDATION_FAILED", "rate the steps in order; future answers stay hidden")
    step = s.get(ReasoningStep, step_id)
    max_points = Decimal(step.max_points)
    ev = StepReviewEvent(id=event_id, user_id=user.id, attempt_id=att.id, step_id=step_id, rating=rating,
                         revealed_before_rating=revealed_before_rating, max_points=max_points,
                         self_score=(max_points * GRADE[rating]).quantize(Decimal("0.01")), algorithm_version=ALGORITHM_VERSION)
    s.add(ev)
    now = utcnow()
    st = s.get(StepReviewState, (user.id, step_id, SCHEDULER_VERSION))
    due = now + timedelta(days=INTERVAL_DAYS[rating])
    if st is None:
        s.add(StepReviewState(user_id=user.id, step_id=step_id, scheduler_version=SCHEDULER_VERSION, due_at=due,
                              review_count=1, last_rating=rating))
    else:
        st.due_at, st.last_rating, st.review_count = due, rating, st.review_count + 1
    # XP is decoupled from the rating so honest "unsure" never costs XP; one award per step per local day.
    local_day = now.astimezone(ZoneInfo(user.timezone or "UTC")).date().isoformat()
    xp = 0
    if s.get(XpAward, (user.id, step_id, local_day)) is None:
        xp = 5 + min(5, math.floor(max_points))
        s.add(XpAward(user_id=user.id, step_id=step_id, local_day=local_day, amount=xp))
    s.flush()
    if all(cid in done | {step_id} for cid in att.card_ids) and att.mode == "due":
        att.state, att.finished_at = "completed", now
    return _review_result(s, ev, replayed=False, xp=xp)


def _review_result(s: Session, ev: StepReviewEvent, replayed: bool, xp: int) -> dict:
    step = s.get(ReasoningStep, ev.step_id)
    st = s.get(StepReviewState, (ev.user_id, ev.step_id, SCHEDULER_VERSION))
    return {"event_id": ev.id, "replayed": replayed, "rating": ev.rating, "self_score": str(ev.self_score),
            "max_points": str(ev.max_points), "xp_awarded": xp, "reference_latex": step.reference_latex,
            "explanation": step.explanation, "next_due_at": st.due_at.isoformat() if st else None}


def knowledge_feedback(s: Session, user: User, attempt_id: str, levels: dict[str, int]) -> dict:
    att = _get_owned(s, user, attempt_id)
    if att.mode != "full":
        raise ApiError("VALIDATION_FAILED", "knowledge feedback applies to full-problem attempts")
    allowed = {c for sid in att.card_ids for c in (s.get(ReasoningStep, sid).knowledge_codes or [])}
    reviewed = {e.step_id for e in s.scalars(select(StepReviewEvent).where(StepReviewEvent.attempt_id == att.id))}
    if set(att.card_ids) - reviewed:
        raise ApiError("VALIDATION_FAILED", "finish all steps first")
    if set(levels) != allowed:
        raise ApiError("VALIDATION_FAILED", "rate exactly the tested knowledge points", {"expected": sorted(allowed)})
    for code, level in levels.items():
        if not isinstance(level, int) or not 1 <= level <= 4:
            raise ApiError("VALIDATION_FAILED", "levels are 1..4")
        if s.scalar(select(KnowledgeSelfAssessment).where(KnowledgeSelfAssessment.attempt_id == att.id,
                                                          KnowledgeSelfAssessment.knowledge_code == code)) is None:
            s.add(KnowledgeSelfAssessment(user_id=user.id, attempt_id=att.id, knowledge_code=code, level=level))
    att.state, att.finished_at = "completed", utcnow()
    s.flush()
    return view(s, user, att.id)


def profile(s: Session, user: User) -> dict:
    """Self-reported evidence index per knowledge code (Beta(2,2) prior). NOT an exam accuracy."""
    stats: dict[str, dict] = {}

    def node(code: str) -> dict:
        title = s.scalar(select(KnowledgeNode.title).where(KnowledgeNode.external_code == code).limit(1)) or code
        return stats.setdefault(code, {"code": code, "title": title, "alpha": PRIOR_ALPHA, "beta": PRIOR_BETA,
                                       "step_observations": 0, "self_assessments": 0})

    events = s.scalars(select(StepReviewEvent).where(StepReviewEvent.user_id == user.id).order_by(StepReviewEvent.occurred_at)).all()
    weak = {}
    calendar: dict[str, int] = {}
    tz = ZoneInfo(user.timezone or "UTC")
    for ev in events:
        step = s.get(ReasoningStep, ev.step_id)
        w = float(ev.max_points) * (0.3 if ev.revealed_before_rating else 1.0)  # peeking lowers evidence weight
        g = float(GRADE[ev.rating])
        for code in step.knowledge_codes or []:
            n = node(code)
            n["alpha"] += w * g
            n["beta"] += w * (1 - g)
            n["step_observations"] += 1
        day = _aware(ev.occurred_at).astimezone(tz).date().isoformat()
        calendar[day] = calendar.get(day, 0) + 1
        if step.criticality == "key":
            if ev.rating in ("fuzzy", "unsure"):
                weak[step.id] = {"step_id": step.id, "recall_cue": step.recall_cue, "rating": ev.rating,
                                 "knowledge_codes": step.knowledge_codes}
            else:
                weak.pop(step.id, None)
    for a in s.scalars(select(KnowledgeSelfAssessment).where(KnowledgeSelfAssessment.user_id == user.id)):
        n = node(a.knowledge_code)
        v = (a.level - 1) / 3
        n["alpha"] += SELF_ASSESS_WEIGHT * v
        n["beta"] += SELF_ASSESS_WEIGHT * (1 - v)
        n["self_assessments"] += 1
    knowledge = []
    for n in stats.values():
        idx = 100 * n["alpha"] / (n["alpha"] + n["beta"])
        knowledge.append({**{k: n[k] for k in ("code", "title", "step_observations", "self_assessments")},
                          "evidence_index": round(idx, 1), "low_sample": n["step_observations"] < 5})
    now = utcnow()
    states = s.scalars(select(StepReviewState).where(StepReviewState.user_id == user.id)).all()
    xp_total = s.scalar(select(func.coalesce(func.sum(XpAward.amount), 0)).where(XpAward.user_id == user.id)) or 0
    return {
        "label": "自评证据指数（主观自报，非考试正确率；样本少时不可比较）",
        "algorithm_version": ALGORITHM_VERSION, "scheduler_version": SCHEDULER_VERSION,
        "knowledge": sorted(knowledge, key=lambda k: k["code"]),
        "due_now": sum(1 for st in states if _aware(st.due_at) <= now),
        "scheduled": len(states),
        "weak_key_steps": list(weak.values())[-8:],
        "xp_total": int(xp_total),
        "calendar": calendar,
        "reviews_total": len(events),
    }

"""Shared API plumbing: DB session per request, auth, idempotency, serializers."""
from __future__ import annotations

import hashlib
import hmac
import os
import secrets
from datetime import timedelta
from decimal import Decimal

from fastapi import Header, Request
from sqlalchemy import select
from sqlalchemy.orm import Session

from ..config import settings
from ..content.contract import canonical_json, sha256_text
from ..models import (
    AuthSession,
    IdempotencyRecord,
    KnowledgeNode,
    Problem,
    ProblemRevision,
    RevisionKnowledge,
    RightsGrant,
    Source,
    SourceRecord,
    Submission,
    User,
    utcnow,
)
from ..services.errors import ApiError


def db(request: Request) -> Session:
    return request.state.db


# ─────────────────────────── passwords & tokens ───────────────────────────
def hash_password(pw: str) -> str:
    salt = os.urandom(16)
    dk = hashlib.scrypt(pw.encode(), salt=salt, n=2**14, r=8, p=1, dklen=32)
    return f"scrypt$16384$8$1${salt.hex()}${dk.hex()}"


def verify_password(pw: str, stored: str) -> bool:
    try:
        _algo, n, r, p, salt, dk = stored.split("$")
        calc = hashlib.scrypt(pw.encode(), salt=bytes.fromhex(salt), n=int(n), r=int(r), p=int(p), dklen=len(bytes.fromhex(dk)))
        return hmac.compare_digest(calc.hex(), dk)
    except (ValueError, TypeError):
        return False


def issue_token(s: Session, user: User) -> str:
    token = secrets.token_urlsafe(32)
    s.add(AuthSession(token_hash=hashlib.sha256(token.encode()).hexdigest(), user_id=user.id,
                      expires_at=utcnow() + timedelta(hours=settings.session_ttl_hours)))
    return token


def _user_from_token(s: Session, authorization: str | None) -> User | None:
    if not authorization or not authorization.lower().startswith("bearer "):
        return None
    token = authorization.split(" ", 1)[1].strip()
    sess = s.get(AuthSession, hashlib.sha256(token.encode()).hexdigest())
    if sess is None or sess.revoked:
        return None
    exp = sess.expires_at if sess.expires_at.tzinfo else sess.expires_at.replace(tzinfo=utcnow().tzinfo)
    if exp <= utcnow():
        return None
    return s.get(User, sess.user_id)


def optional_user(request: Request, authorization: str | None = Header(default=None)) -> User | None:
    return _user_from_token(request.state.db, authorization)


def current_user(request: Request, authorization: str | None = Header(default=None)) -> User:
    u = _user_from_token(request.state.db, authorization)
    if u is None:
        raise ApiError("AUTH_REQUIRED", "login required")
    return u


# ─────────────────────────── generic idempotency ───────────────────────────
def idempotent(s: Session, scope: str, key: str | None, body: dict, fn) -> tuple[int, dict]:
    """Replay-safe POST. Same key + same body → stored response; same key + other body → 409."""
    if not key:
        return fn()
    if not 8 <= len(key) <= 128:
        raise ApiError("VALIDATION_FAILED", "Idempotency-Key must be 8..128 chars")
    h = sha256_text(canonical_json(body))
    rec = s.get(IdempotencyRecord, (scope, key))
    if rec is not None:
        if rec.request_hash != h:
            raise ApiError("IDEMPOTENCY_CONFLICT", "Idempotency-Key reused with a different request")
        return rec.status_code, rec.response
    status, resp = fn()
    s.add(IdempotencyRecord(scope=scope, key=key, request_hash=h, status_code=status, response=resp))
    return status, resp


# ─────────────────────────── serializers ───────────────────────────
def dec(v) -> str | None:
    return None if v is None else str(Decimal(v).quantize(Decimal("0.01")))


def user_out(u: User) -> dict:
    return {"id": u.id, "username": u.username, "display_name": u.display_name, "roles": sorted(u.role_set)}


def knowledge_summaries(s: Session, rev: ProblemRevision) -> list[dict]:
    rows = s.execute(select(KnowledgeNode, RevisionKnowledge.relation_type)
                     .join(RevisionKnowledge, RevisionKnowledge.knowledge_node_id == KnowledgeNode.id)
                     .where(RevisionKnowledge.revision_id == rev.id)).all()
    return [{"id": n.id, "code": n.external_code, "title": n.title, "relation": rel} for n, rel in rows]


def source_attribution(s: Session, problem: Problem, rev: ProblemRevision) -> list[dict]:
    out = []
    grant = s.get(RightsGrant, rev.rights_grant_id) if rev.rights_grant_id else None
    for sr in s.scalars(select(SourceRecord).where(SourceRecord.canonical_problem_id == problem.id)):
        src = s.get(Source, sr.source_id)
        out.append({"source": src.name, "source_code": src.code, "kind": src.kind, "relation": sr.relation_to_problem,
                    "external_id": sr.external_id if src.kind != "teacher_private" else None})
    if not out:
        for ref in (rev.content_metadata or {}).get("_source_record_refs", []):
            src = s.scalar(select(Source).where(Source.code == ref["source_code"]))
            out.append({"source": src.name if src else ref["source_code"], "source_code": ref["source_code"],
                        "kind": src.kind if src else None, "relation": "origin", "note": ref.get("note")})
    if grant and grant.attribution_text:
        out.append({"attribution": grant.attribution_text})
    return out


def input_hint(part) -> dict:
    spec = part.answer_specs[-1]
    hint = {"response_type": part.response_type, "grading_mode": spec.grading_mode}
    if part.response_type in ("expression", "interval", "set", "equation_set"):
        hint["variables"] = spec.spec.get("assumptions", {})
        if spec.spec.get("solve_for"):
            hint["solve_for"] = spec.spec["solve_for"]
    if spec.spec.get("tolerance"):
        hint["tolerance"] = spec.spec["tolerance"]
    if spec.spec.get("unit"):
        hint["unit"] = spec.spec["unit"]
    return hint


def solutions_visible(s: Session, rev: ProblemRevision, part_id: str, user: User | None) -> bool:
    policy = (rev.content_metadata or {}).get("solution_visibility", "after_submit")
    if policy == "always":
        return True
    if user is None:
        return False
    if user.role_set & {"editor", "reviewer", "admin"}:
        return True
    if policy == "teacher_release":
        return False
    return s.scalar(select(Submission.id).where(Submission.user_id == user.id, Submission.revision_part_id == part_id).limit(1)) is not None


def revision_public_view(s: Session, problem: Problem, rev: ProblemRevision, user: User | None) -> dict:
    parts = []
    for p in rev.parts:
        pd = {"id": p.id, "logical_part_id": p.logical_part_id, "part_key": p.part_key, "display_order": p.display_order,
              "response_type": p.response_type, "max_score": dec(p.max_score), "prompt": p.prompt,
              "input": input_hint(p), "grading_suspended": p.grading_suspended, "knowledge_codes": p.knowledge_codes}
        if p.options:
            pd["options"] = p.options
        if solutions_visible(s, rev, p.id, user):
            pd["solutions"] = [{"type": so.solution_type, **so.content} for so in p.solutions]
        else:
            pd["solutions_locked"] = bool(p.solutions)
        parts.append(pd)
    md = rev.content_metadata or {}
    return {
        "id": rev.id, "revision_no": rev.revision_no, "locale": rev.locale, "title": rev.title,
        "status": rev.status, "published_at": rev.published_at.isoformat() if rev.published_at else None,
        "shared_statement": rev.shared_statement, "parts": parts,
        "difficulty": rev.platform_difficulty, "region_hints": md.get("region_hints", []),
        "problem_type": md.get("problem_type", []), "tags": md.get("tags", []),
        "verified_exam": bool(md.get("verified_exam")),
        "knowledge": knowledge_summaries(s, rev),
        "source_attribution": source_attribution(s, problem, rev),
        "visible_solutions_policy": md.get("solution_visibility", "after_submit"),
        "total_score": dec(sum(Decimal(p.max_score) for p in rev.parts)),
    }

